+/*
+ * Correlate an EAPOL descriptor's host-side submit and terminal CFM without
+ * changing the descriptor ABI that libwifi.a consumes.  The opaque MAC owns
+ * the status writeback; this probe only shows which registered MAC IRQ
+ * sources ran between enqueue and the CFM event.
+ *
+ * The table is intentionally small: WPA M2/M4 frames are serialized and the
+ * entry is removed at terminal confirmation.  If every slot is occupied, the
+ * probe simply skips the frame rather than perturbing TX ownership.
+ */
+#define RWNX_EAPOL_CFM_PROBE_SLOTS 4
+
+struct rwnx_eapol_cfm_probe_s
+{
+	struct txdesc *txdesc;
+	uint32_t isr31;
+	uint32_t isr33;
+	uint32_t isr34;
+	uint32_t isr35;
+	uint32_t isr36;
+};
+
+extern volatile uint32_t bk7258_wifi_isr_count[64];
+
+static struct rwnx_eapol_cfm_probe_s
+	g_rwnx_eapol_cfm_probe[RWNX_EAPOL_CFM_PROBE_SLOTS];
+
+static void rwnx_eapol_cfm_probe_submit(struct txdesc *txdesc)
+{
+	uint32_t slot;
+	uint32_t empty = RWNX_EAPOL_CFM_PROBE_SLOTS;
+	GLOBAL_INT_DECLARATION();
+
+	GLOBAL_INT_DISABLE();
+	for (slot = 0; slot < RWNX_EAPOL_CFM_PROBE_SLOTS; slot++)
+	{
+		if (g_rwnx_eapol_cfm_probe[slot].txdesc == txdesc)
+		{
+			empty = slot;
+			break;
+		}
+
+		if (g_rwnx_eapol_cfm_probe[slot].txdesc == NULL &&
+			empty == RWNX_EAPOL_CFM_PROBE_SLOTS)
+		{
+			empty = slot;
+		}
+	}
+
+	if (empty < RWNX_EAPOL_CFM_PROBE_SLOTS)
+	{
+		g_rwnx_eapol_cfm_probe[empty].txdesc = txdesc;
+		g_rwnx_eapol_cfm_probe[empty].isr31 = bk7258_wifi_isr_count[31];
+		g_rwnx_eapol_cfm_probe[empty].isr33 = bk7258_wifi_isr_count[33];
+		g_rwnx_eapol_cfm_probe[empty].isr34 = bk7258_wifi_isr_count[34];
+		g_rwnx_eapol_cfm_probe[empty].isr35 = bk7258_wifi_isr_count[35];
+		g_rwnx_eapol_cfm_probe[empty].isr36 = bk7258_wifi_isr_count[36];
+	}
+	GLOBAL_INT_RESTORE();
+}
+
+static bool rwnx_eapol_cfm_probe_take(struct txdesc *txdesc,
+		struct rwnx_eapol_cfm_probe_s *probe)
+{
+	uint32_t slot;
+	bool found = false;
+	GLOBAL_INT_DECLARATION();
+
+	GLOBAL_INT_DISABLE();
+	for (slot = 0; slot < RWNX_EAPOL_CFM_PROBE_SLOTS; slot++)
+	{
+		if (g_rwnx_eapol_cfm_probe[slot].txdesc == txdesc)
+		{
+			*probe = g_rwnx_eapol_cfm_probe[slot];
+			g_rwnx_eapol_cfm_probe[slot].txdesc = NULL;
+			found = true;
+			break;
+		}
+	}
+	GLOBAL_INT_RESTORE();
+
+	return found;
+}
+

 /// Length of a char in bytes
